"use strict";

// ── Standard CRG requires ────────────────────────────────────────────────────
const fs   = require("fs");
const path = require("path");

const { requireEnv, optionalEnv } = require("./_lib/env");
const agentGuard                  = require("./_lib/agent-guard");
